from pathlib import Path
import ast, copy

# Collect function signatures from ledgerly source.
funcs = {}
for p in Path('ledgerly').rglob('*.py'):
    tree = ast.parse(p.read_text())
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            args = node.args
            defaults = [None] * (len(args.args) - len(args.defaults)) + list(args.defaults)
            params = []
            for a, d in zip(args.args, defaults):
                kind = a.annotation.id if isinstance(a.annotation, ast.Name) else None
                params.append({'name': a.arg, 'kind': kind, 'default': d})
            ret = node.returns.id if isinstance(node.returns, ast.Name) else None
            funcs[node.name] = {'params': params, 'ret': ret}

def num_value(n):
    if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and not isinstance(n.value, bool):
        return n.value
    if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.USub, ast.UAdd)):
        v = num_value(n.operand)
        if v is not None:
            return -v if isinstance(n.op, ast.USub) else v
    return None

def wrapper(name, value, currency):
    return ast.Call(
        func=ast.Name(id=name, ctx=ast.Load()),
        args=[
            ast.Call(func=ast.Name(id='Decimal', ctx=ast.Load()),
                     args=[ast.Constant(value=str(value))], keywords=[]),
            copy.deepcopy(currency),
        ],
        keywords=[],
    )

def wrap_money(node, currency):
    v = num_value(node)
    if v is not None:
        return wrapper('Money', v, currency)
    return node

def wrap_decimal(node):
    v = num_value(node)
    if v is not None:
        return ast.Call(func=ast.Name(id='Decimal', ctx=ast.Load()),
                        args=[ast.Constant(value=str(v))], keywords=[])
    return node

def bindings(spec, call):
    b = {}
    for i, arg in enumerate(call.args):
        if i < len(spec['params']):
            b[spec['params'][i]['name']] = arg
    for kw in call.keywords:
        if kw.arg:
            b[kw.arg] = kw.value
    for p in spec['params']:
        if p['name'] not in b and p['default'] is not None:
            b[p['name']] = p['default']
    return b

def currency_for(spec, b, result=False):
    if result and 'dst' in b:
        return b['dst']
    if 'currency' in b:
        return b['currency']
    if 'src' in b:
        return b['src']
    return ast.Constant(value='USD')

class TestTransformer(ast.NodeTransformer):
    def visit_Call(self, node):
        # Transform children first, but not the call's own arguments twice.
        self.generic_visit(node)
        if not isinstance(node.func, ast.Name) or node.func.id not in funcs:
            return node
        name = node.func.id
        spec = funcs[name]
        b = bindings(spec, node)
        cur = currency_for(spec, b)
        for i, arg in enumerate(node.args):
            if i >= len(spec['params']):
                continue
            p = spec['params'][i]
            if p['kind'] == 'Money':
                if name in ('invoice_json',):
                    # lines is a list of (sku, Money) pairs
                    if isinstance(arg, ast.List):
                        for elt in arg.elts:
                            if isinstance(elt, ast.Tuple) and len(elt.elts) >= 2:
                                elt.elts[1] = wrap_money(elt.elts[1], cur)
                elif name == 'ledger_csv':
                    # rows is a list of (date, memo, Money) triples
                    if isinstance(arg, ast.List):
                        for elt in arg.elts:
                            if isinstance(elt, ast.Tuple) and len(elt.elts) >= 3:
                                elt.elts[2] = wrap_money(elt.elts[2], cur)
                elif isinstance(arg, (ast.List, ast.Tuple)):
                    arg.elts = [wrap_money(e, cur) for e in arg.elts]
                else:
                    node.args[i] = wrap_money(arg, cur)
            elif p['kind'] == 'Decimal':
                node.args[i] = wrap_decimal(arg)
        # Re-bind in case argument transforms changed nothing important.
        b = bindings(spec, node)
        cur = currency_for(spec, b)
        for kw in node.keywords:
            spec_p = next((p for p in spec['params'] if p['name'] == kw.arg), None)
            if spec_p and spec_p['kind'] == 'Money':
                kw.value = wrap_money(kw.value, cur)
            elif spec_p and spec_p['kind'] == 'Decimal':
                kw.value = wrap_decimal(kw.value)
        return node

    def visit_AssertEqual(self, node):
        self.generic_visit(node)
        if len(node.args) < 2:
            return node
        first, second = node.args[0], node.args[1]
        if not (isinstance(first, ast.Call) and isinstance(first.func, ast.Name) and first.func.id in funcs):
            return node
        spec = funcs[first.func.id]
        b = bindings(spec, first)
        cur = currency_for(spec, b, result=True)
        if spec['ret'] == 'Money':
            node.args[1] = wrap_money(second, cur)
        elif spec['ret'] == 'list':
            if isinstance(second, ast.List):
                second.elts = [wrap_money(e, cur) for e in second.elts]
        return node

